import test from 'node:test';
import assert from 'node:assert/strict';
import {earnOpening} from './opening-flow.mjs';
import {investigationView,validateExploration} from '../exploration.js';
import {EXPLORATION_CONTENT} from '../exploration-content.js';

function visit(chapter){const h=earnOpening(),w=h.w;w.state.chapter=Math.max(chapter,w.state.chapter);w.loadScene(700+chapter);h.finish();return {...h,w,useRole(role){const o=w.scene.objects.find(o=>o.investigationRole===role);w.state.x=o.xy[0]+.5;w.state.y=o.xy[1]+.5;h.use(o);},pick(label){const at=h.dialog?.choices?.findIndex(c=>c.label.includes(label));assert.ok(at>=0,'Missing action '+label);h.choose(at);},claim(){const o=w.scene.objects.find(o=>o.exploreId==='district:'+chapter+':keepsake');w.state.x=o.xy[0]+.5;w.state.y=o.xy[1]+.5;h.use(o);}};}
test('ordinary optional latches vary their answer position and keep evidence outside the question',()=>{const {w}=earnOpening(),slots=new Set();for(let n=1;n<=24;n++){const latch=w.scenes.get(700+n).objects.find(o=>o.type==='riddle');if(latch.investigationRole)continue;slots.add(latch.answer);assert.notEqual(latch.prompt,EXPLORATION_CONTENT[n-1].clue);assert.equal(latch.options[latch.answer],EXPLORATION_CONTENT[n-1].answer);}assert.equal(slots.size,3);});
test('leak tracing changes a real ordered mechanism, survives a reload and does not grant story flags',()=>{const h=visit(3),w=h.w,flags=JSON.stringify(w.state.flags),items={...w.state.items};h.useRole('work');h.pick('Lift and clear');assert.equal(investigationView(w.state,3).drained,false);h.useRole('evidence');h.pick('Trace the seep');h.useRole('control');h.pick('Close the supply');w.restore(w.save());h.finish();h.useRole('work');h.pick('Lift and clear');assert.equal(investigationView(w.state,3).drained,false);h.useRole('control');h.pick('Open the relief');h.useRole('work');h.pick('Lift and clear');assert.ok(w.state.exploration.solved.includes('district:3:latch'));assert.equal(JSON.stringify(w.state.flags),flags);assert.deepEqual(w.state.items,items);h.claim();const saved=w.save();h.claim();assert.equal(w.save(),saved);});
test('the vestry distinguishes a silence from another pull and preserves a valid prefix',()=>{const h=visit(4),w=h.w;const act=label=>{h.useRole('control');h.pick(label);};act('small');act('deep');assert.equal(investigationView(w.state,4).phrase,0);act('small');act('settle');w.restore(w.save());h.finish();act('deep');act('small');assert.ok(w.state.exploration.solved.includes('district:4:latch'));h.claim();assert.ok(w.state.exploration.found.includes('district:4:keepsake'));});
test('the carrier must actually leave the tray uncovered; a repeated guess does not advance their routine',()=>{const h=visit(5),w=h.w;h.useRole('control');h.pick('Draw the uncovered');assert.equal(investigationView(w.state,5).phase,0);assert.equal(w.state.exploration.solved.includes('district:5:latch'),false);for(let i=0;i<2;i++){h.useRole('evidence');h.pick('Watch the next');}assert.equal(investigationView(w.state,5).phase,2);h.useRole('control');h.pick('Draw the uncovered');assert.ok(w.state.exploration.solved.includes('district:5:latch'));});
test('creature custody requires shelter and finite local food, preserves either decision, and rests only once',()=>{for(const choice of ['Open the shelter','Keep the planter']){const h=visit(7),w=h.w,items={...w.state.items};h.useRole('work');h.pick('Offer the fallen');assert.equal(w.state.exploration.solved.includes('district:7:latch'),false);h.useRole('evidence');h.pick('Take only');h.useRole('control');h.pick('Raise the mat');h.useRole('work');h.pick('Offer the fallen');h.pick(choice);assert.ok(w.state.exploration.solved.includes('district:7:latch'));assert.deepEqual(w.state.items,items);const outcome=investigationView(w.state,7).custody;assert.equal(outcome,choice.startsWith('Open')?'released':'sheltered');w.restore(w.save());h.finish();w.activeHeroes[0].strain=30;h.useRole('work');h.pick('Sit quietly');assert.equal(w.activeHeroes[0].strain,20);h.useRole('work');h.pick('Sit quietly');assert.equal(w.activeHeroes[0].strain,20);assert.equal(investigationView(w.state,7).custody,outcome);}});
test('authored sites reject remote activation and legacy solved rooms retain their rewards without replay',()=>{const h=visit(4),w=h.w,o=w.scene.objects.find(o=>o.investigationRole==='control');w.state.x=-20;w.state.y=-20;w.interact(o);assert.equal(w.state.exploration.investigations,undefined);w.state.exploration.solved.push('district:4:latch');h.useRole('control');h.claim();assert.ok(w.state.exploration.found.includes('district:4:keepsake'));});
test('investigation validation accepts old ledgers and rejects impossible or unbounded state',()=>{const base={version:1,found:[],solved:[],seen:[],relics:[]};validateExploration({exploration:base});for(const investigations of [{'4':{phrase:5}},{'3':{isolated:'yes'}},{'7':{custody:'dead'}},{'99':{}}])assert.throws(()=>validateExploration({exploration:{...base,investigations}}),/investigation/);});
